DO $p3c_do$
DECLARE
  v_data jsonb := $p3c_json${"standard":{"code":"FLL-GAR-2023","title_de":"Gewaesserabdichtungsrichtlinien - Richtlinien fuer Planung, Bau und Instandhaltung von Gewaesserabdichtungen","title_en":"Water-Body Sealing Guidelines - Guidelines for Planning, Construction and Maintenance of Water-Body Seals","version":"Dezember 2023 (2. Ausgabe; Erstauflage 2005)"},"worksheets":[{"code":"FLL-GAR-01","title_de":"Projektregistrierung","title_en":"Project Registration","phase":1,"archetype":"registration","order_index":1,"description":"Administrative project data: Bauherr, Planer, Ausfuehrungsbetrieb, project location, dates."},{"code":"FLL-GAR-02","title_de":"Anwendungsbereich & Abgrenzung","title_en":"Scope & Applicability","phase":1,"archetype":"data_collection","order_index":2,"description":"Confirm scope: pond, basin, stream, swim/bathing pond, retention basin, etc. Exclude landfills, fisheries, dams, waterways."},{"code":"FLL-GAR-03","title_de":"Baurechtliche Anforderungen","title_en":"Building-Law Requirements","phase":1,"archetype":"data_collection","order_index":3,"description":"Required authorities, permits (LBO, WHG), insurance and safety obligations (Absturzsicherung, Ertrinken)."},{"code":"FLL-GAR-04","title_de":"Nutzungsfestlegung","title_en":"Usage Definition","phase":2,"archetype":"data_collection","order_index":4,"description":"Define water-body function (Loeschwasser, RRB, Schwimmteich etc.) which drives material, dimensions, protection measures."},{"code":"FLL-GAR-05","title_de":"Einwirkungen und Beanspruchungen","title_en":"Loads and Stresses","phase":2,"archetype":"data_collection","order_index":5,"description":"Document mechanical, thermal, chemical and biological loads; Wassereinwirkungsklasse W1-B...W3-B; Rissklasse R0-B...R3-B; Standort S1-B/S2-B."},{"code":"FLL-GAR-06","title_de":"Baugrund und Untergrund","title_en":"Subsoil and Substrate","phase":2,"archetype":"data_collection","order_index":6,"description":"Subsoil investigation, frost depth, bearing capacity, fines content, presence of stones, organic matter."},{"code":"FLL-GAR-07","title_de":"Profilierung und Boeschungsneigung","title_en":"Profiling and Slope","phase":3,"archetype":"calculation","order_index":7,"description":"Profile design; material-specific slope limits per Tab. 1 (1:1...1:5 depending on Werkstoff)."},{"code":"FLL-GAR-08","title_de":"Bauliche Erfordernisse","title_en":"Constructional Requirements","phase":3,"archetype":"data_collection","order_index":8,"description":"Gewaessertrennung, accommodation of building movements / cracks, ice-pressure protection."},{"code":"FLL-GAR-09","title_de":"Abdichtungssystem Auswahl","title_en":"Sealing System Selection","phase":3,"archetype":"verification","order_index":9,"description":"Select sealing type considering usage, geometry, einwirkungsklasse, root/rhizome aggressiveness; CE/EU-BauPVO/MVV-TB compliance check."},{"code":"FLL-GAR-10","title_de":"Mineralisch ohne Zusatzstoffe","title_en":"Mineral without Additives","phase":4,"archetype":"calculation","order_index":10,"description":"Design with raw/homogenised/vacuum-pressed clay (Grubentone); kf, organic content, calcium content, compaction."},{"code":"FLL-GAR-11","title_de":"Mineralisch mit Zusatzstoffen","title_en":"Mineral with Additives","phase":4,"archetype":"calculation","order_index":11,"description":"Bentonite, clay-meal, polymer additives; admixed-in-place / plant-mixed; Eignungspruefung essential."},{"code":"FLL-GAR-12","title_de":"Mineralisch mit hydraulischen Bindemitteln (Beton)","title_en":"Mineral with Hydraulic Binders (Concrete)","phase":4,"archetype":"calculation","order_index":12,"description":"Ortbeton / Spritzbeton / Elementwaende / Fertigteile; high water-penetration resistance per DAfStb WU-Richtlinie."},{"code":"FLL-GAR-13","title_de":"Mineralisch mit Bitumen (Asphalt)","title_en":"Mineral with Bitumen (Asphalt)","phase":4,"archetype":"calculation","order_index":13,"description":"Asphaltmastix, Gussasphalt, water-tight Asphaltbeton."},{"code":"FLL-GAR-14","title_de":"Verbundwerkstoffe (GTD)","title_en":"Composite Materials (GCL)","phase":4,"archetype":"calculation","order_index":14,"description":"Geosynthetic clay liners (Bentonitmatten / GTD / GBR-C); Na- vs Ca-bentonite, geotextile cover, optional polyolefin coating."},{"code":"FLL-GAR-15","title_de":"Bitumenbahnen","title_en":"Bituminous Sheet Membranes","phase":4,"archetype":"calculation","order_index":15,"description":"Multi-layer bitumen and polymer-bitumen sheets (G 200 DD, PV 200 DD, PYE PV 200 S5 etc.) per DIN 18535-2 / DIN 18533-2."},{"code":"FLL-GAR-16","title_de":"Kunststoff-/Elastomerbahnen","title_en":"Plastic / Elastomeric Sheet Membranes","phase":4,"archetype":"calculation","order_index":16,"description":"PVC-P, EPDM, EVA, FPO, PIB, TPE, ECB sheets; thickness >= 1.2 mm (1.0 mm for prefab garden ponds); joint widths."},{"code":"FLL-GAR-17","title_de":"Fluessigkunststoff","title_en":"Liquid-Applied Plastic","phase":4,"archetype":"calculation","order_index":17,"description":"Liquid-applied plastic sealing per DIN 18531-2 / DIN 18533-3 with classification per Annex 3 (M/S, W1-W3, P1-P4, S1-S4, TL/TH)."},{"code":"FLL-GAR-18","title_de":"Kunststoffbahnen aus PE (PELD/PEHD)","title_en":"Polyethylene Sheet Membranes (PELD/PEHD)","phase":4,"archetype":"calculation","order_index":18,"description":"PELD / PEHD sheets; PEHD has inherent root/rhizome resistance (no FLL test required); PELD requires FLL root-resistance proof."},{"code":"FLL-GAR-19","title_de":"Stahl","title_en":"Steel","phase":4,"archetype":"calculation","order_index":19,"description":"V2A (1.4301), V4A (1.4401), V5A (1.4539) and weather-resistant CorTen steels; zinc-coating thickness >= 100 micrometers for unalloyed steel."},{"code":"FLL-GAR-20","title_de":"Alkalisilikate","title_en":"Alkali Silicates","phase":4,"archetype":"calculation","order_index":20,"description":"Sodium/lithium/potassium water-glass admixed in clay/loam soils; potassium-water-glass only is plant-compatible."},{"code":"FLL-GAR-21","title_de":"GUP (glasfaserverstaerktes Polyester)","title_en":"GRP (Glass-Fibre Reinforced Polyester)","phase":4,"archetype":"calculation","order_index":21,"description":"Prefabricated GRP / glass-reinforced unsaturated polyester elements; manufacturer's edge formation predominates."},{"code":"FLL-GAR-22","title_de":"Schutzlagen und Schutzschichten","title_en":"Protection Layers / Schichten","phase":5,"archetype":"calculation","order_index":22,"description":"Above / below abdichtung protection vs. mechanical, thermal, chemical loads; Schutzwirksamkeitsklassen per DIN EN 13719."},{"code":"FLL-GAR-23","title_de":"Randausbildungen","title_en":"Edge Formations","phase":5,"archetype":"calculation","order_index":23,"description":"Min. height of edge above water-line (>= 5 cm to terrain, >= 30 cm to building, reducible to >= 15 cm with adapted fastening)."},{"code":"FLL-GAR-24","title_de":"Bepflanzung und Einbauten","title_en":"Planting and Installations","phase":5,"archetype":"data_collection","order_index":24,"description":"Plant choice, rhizome aggressiveness (Phragmites, Typha etc.), test methods (FLL-Wurzelpruefung, Rhizompruefung)."},{"code":"FLL-GAR-25","title_de":"Pruefungen (Eignung / Eigen- / Fremd- / Kontroll-)","title_en":"Tests (Suitability / Self / External / Control)","phase":6,"archetype":"verification","order_index":25,"description":"All test categories: Voruntersuchung, Eignungspruefung, Eigenueberwachung, Fremdueberwachung, Kontrollpruefung."},{"code":"FLL-GAR-26","title_de":"Abnahme und Maengelanspruechen","title_en":"Acceptance and Defects","phase":6,"archetype":"verification","order_index":26,"description":"Formal acceptance, 5-year defects-liability period including vegetation work where bundled with sealing work."},{"code":"FLL-GAR-27","title_de":"Inbetriebnahme","title_en":"Commissioning","phase":6,"archetype":"verification","order_index":27,"description":"Activation of pumps / Notueberlauf, first filling, fold smoothing, function checks of capillary barrier and overflow."},{"code":"FLL-GAR-28","title_de":"Instandhaltung (Inspektion / Wartung / Instandsetzung)","title_en":"Maintenance (Inspection / Servicing / Repair)","phase":6,"archetype":"verification","order_index":28,"description":"Minimum yearly inspection (DIN 31051); maintenance concept (intervals, scope); repair triggers."},{"code":"FLL-GAR-29","title_de":"Konformitaetszusammenfassung & Freigabe","title_en":"Compliance Summary & Sign-off","phase":6,"archetype":"summary","order_index":29,"description":"Aggregation of all section results, verdict (compliant / compliant-with-conditions / not-compliant), engineer + customer sign-off."}],"sections":[{"ws_code":"FLL-GAR-01","code":"A","title_de":"Purpose and Context","order_index":1,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"B","title_de":"Input Parameters","order_index":2,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"C","title_de":"Worksheet-Specific Content (main body)","order_index":3,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"D","title_de":"Results / Derived Values","order_index":4,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"F","title_de":"Results Summary","order_index":5,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"J","title_de":"Output Transfer Table","order_index":6,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"K","title_de":"Notes and Assumptions","order_index":7,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"L","title_de":"Approval (signatures)","order_index":8,"parent_code":null},{"ws_code":"FLL-GAR-01","code":"M","title_de":"Workflow Connection","order_index":9,"parent_code":null},{"ws_code":"FLL-GAR-02","code":"A","title_de":"Purpose and Context","order_index":1,"parent_code":null},{"ws_code":"FLL-GAR-02","code":"B","title_de":"Input Parameters","order_index":2,"parent_code":null},{"ws_code":"FLL-GAR-02","code":"C","title_de":"Worksheet-Specific Content (main body)","order_index":3,"parent_code":null},{"ws_