_index":3,"regulation_reference":"Tab.28"}],"validation_rules":{"raw":"enum: abschluss_anwendungsfall"},"clause_reference":"Tab.28","description":"Bauteil/Bauwerk vs Freiflaeche vs Schwimmteich - drives An-/Abschlusshoehe minimum.","consumer_worksheets":null},{"ws_code":"FLL-GAR-24","section_code":"B","symbol":"mit_bepflanzung","label_de":"Mit Bepflanzung","label_en":"With planting","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"true/false"},"clause_reference":"Sec.7.2; Sec.10","description":"Whether the water body will have plants - scopes phytotoxicity rule for Alkali silicates.","consumer_worksheets":["FLL-GAR-09","FLL-GAR-20"]},{"ws_code":"FLL-GAR-20","section_code":"C","symbol":"alkalisilikat_type","label_de":"Alkalisilikat-Typ","label_en":"Alkali silicate type","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"Na","label_de":"Natrium-Wasserglas","label_en":"Sodium water-glass","order_index":1,"regulation_reference":"Sec.7.2"},{"value":"Li","label_de":"Lithium-Wasserglas","label_en":"Lithium water-glass","order_index":2,"regulation_reference":"Sec.7.2"},{"value":"K","label_de":"Kalium-Wasserglas","label_en":"Potassium water-glass","order_index":3,"regulation_reference":"Sec.7.2"}],"validation_rules":{"raw":"enum: alkalisilikat_type"},"clause_reference":"Sec.7.2","description":"Na-/Li-/K-water-glass - scopes phytotoxicity rule.","consumer_worksheets":null},{"ws_code":"FLL-GAR-19","section_code":"C","symbol":"stahl_typ","label_de":"Stahl-Typ","label_en":"Steel grade","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"V2A","label_de":"Edelstahl V2A (1.4301)","label_en":"Stainless steel V2A (1.4301)","order_index":1,"regulation_reference":"Sec.7.1"},{"value":"V4A","label_de":"Edelstahl V4A (1.4401)","label_en":"Stainless steel V4A (1.4401)","order_index":2,"regulation_reference":"Sec.7.1"},{"value":"V5A","label_de":"Edelstahl V5A (1.4539)","label_en":"Stainless steel V5A (1.4539)","order_index":3,"regulation_reference":"Sec.7.1"},{"value":"CorTen_A","label_de":"Wetterfester Baustahl CorTen A (1.8946)","label_en":"Weathering steel CorTen A (1.8946)","order_index":4,"regulation_reference":"Sec.7.1"},{"value":"CorTen_B","label_de":"Wetterfester Baustahl CorTen B (1.8965)","label_en":"Weathering steel CorTen B (1.8965)","order_index":5,"regulation_reference":"Sec.7.1"},{"value":"unlegiert","label_de":"Unlegierter Stahl (feuerverzinkt)","label_en":"Unalloyed steel (galvanised)","order_index":6,"regulation_reference":"Sec.7.1"}],"validation_rules":{"raw":"enum: stahl_typ"},"clause_reference":"Sec.7.1","description":"V2A / V4A / V5A / CorTen A / CorTen B / unlegiert.","consumer_worksheets":null},{"ws_code":"FLL-GAR-19","section_code":"C","symbol":"verzinkung_dicke_um","label_de":"Verzinkungsdicke","label_en":"Galvanisation thickness","data_type":"number","unit":"micrometer","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 100 (unlegiert)"},"clause_reference":"Sec.7.1","description":"Zinc-coating thickness for unalloyed steel (Schmelztauchen / Feuerverzinken).","consumer_worksheets":null},{"ws_code":"FLL-GAR-13","section_code":"C","symbol":"hohlraumgehalt_asphaltbeton_vol_pct","label_de":"Hohlraumgehalt Asphaltbeton","label_en":"Asphalt-concrete void content","data_type":"number","unit":"Vol.-%","is_required":true,"enum_values":null,"validation_rules":{"raw":"<= 3"},"clause_reference":"Sec.5.4.1.1; Tab.12 note 1","description":"Void content in installed Asphaltbeton sealing layer.","consumer_worksheets":null},{"ws_code":"FLL-GAR-20","section_code":"C","symbol":"feinkornanteil_063_pct","label_de":"Feinkornanteil <0,063 mm","label_en":"Fines fraction < 0.063 mm","data_type":"number","unit":"Masse-%","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 20 (Alkalisilikat)"},"clause_reference":"Sec.7.2.1","description":"Fine-particle content of host soil for Alkali-silicate sealing.","consumer_worksheets":null},{"ws_code":"FLL-GAR-14","section_code":"C","symbol":"gtd_ueberlappung_laengs_cm","label_de":"GTD-Ueberlappung laengs","label_en":"GCL longitudinal overlap","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 30"},"clause_reference":"Sec.5.5.2.1","description":"Longitudinal overlap of GCL rolls.","consumer_worksheets":null},{"ws_code":"FLL-GAR-14","section_code":"C","symbol":"gtd_ueberlappung_quer_cm","label_de":"GTD-Ueberlappung quer","label_en":"GCL transverse overlap","data_type":"number","unit":"cm","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 50"},"clause_reference":"Sec.5.5.2.1","description":"Transverse overlap at end of each GCL roll.","consumer_worksheets":null},{"ws_code":"FLL-GAR-14","section_code":"C","symbol":"groesstkorn_auflast_mm","label_de":"Groesstkorn Auflast","label_en":"Cover-load max grain size","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":"<= 16 (or <= 32 if U>=5)"},"clause_reference":"Sec.5.5.2.1","description":"Max grain size of cover material above GCL.","consumer_worksheets":null},{"ws_code":"FLL-GAR-18","section_code":"C","symbol":"naht_pe_ueberlappung_mm","label_de":"Nahtueberlappung PE-Bahn","label_en":"PE sheet joint overlap","data_type":"number","unit":"mm","is_required":true,"enum_values":null,"validation_rules":{"raw":"100-150"},"clause_reference":"Sec.6.4.2.1","description":"Overlap of PE sheet joints (Schweissverfahren).","consumer_worksheets":null}],"equations":[{"ws_code":"FLL-GAR-27","equation_number":"1","formula":"Q_NOT = (r_5_100 - r_5_5 * C) * (A / 10000)","input_symbols":["r_5_100","r_5_5","C","A"],"output_symbol":"Q_NOT","clause_reference":"Anhang 1 (informativ)","description":"Notueberlauf-Bemessung (Beispiel) - referenziert DIN 1986-100"},{"ws_code":"FLL-GAR-22","equation_number":"2a","formula":"g_prime = gamma_D_prime * d_D","input_symbols":["gamma_D_prime","d_D"],"output_symbol":"g_prime","clause_reference":"Anhang 2 (informativ)","description":"Definition Flaechengewicht der Auflast (Anhang 2)"},{"ws_code":"FLL-GAR-22","equation_number":"2b","formula":"g_prime >= (Delta_u * gamma_A - (gamma_F_prime * d_F + gamma_Di_prime * d_Di)) / cos(beta)","input_symbols":["Delta_u","gamma_A","gamma_F_prime","d_F","gamma_Di_prime","d_Di","beta"],"output_symbol":"g_prime","clause_reference":"Anhang 2 (informativ)","description":"Anforderung Flaechengewicht der Auflast gegen Abheben (Anhang 2)"},{"ws_code":"FLL-GAR-22","equation_number":"2c","formula":"Delta_u = (Delta_h_W + z_a) * gamma_w","input_symbols":["Delta_h_W","z_a","gamma_w"],"output_symbol":"Delta_u","clause_reference":"Anhang 2 (informativ)","description":"Hilfsgleichung Porenwasserueberdruck Delta_u (Anhang 2)"}],"compliance":[{"ws_code":"FLL-GAR-01","code":"REQ-01","title_de":"Geltungsbereich abgegrenzt","condition":"gewaesser_in_scope == true","description":"Confirm water-body type is in scope (not a landfill, fishery, dam, or waterway).","clause_reference":"Sec.1.1"},{"ws_code":"FLL-GAR-01","code":"REQ-02","title_de":"Baurechtliche Genehmigungen geprueft","condition":"lbo_genehmigung_erforderlich is set (true or false)","description":"Required LBO building permits identified and applied for.","clause_reference":"Sec.4.1; Sec.4.2"},{"ws_code":"FLL-GAR-01","code":"REQ-03","title_de":"WHG-Einleitungsgenehmigung geklaert","condition":"whg_einleitung_genehmigung is set","description":"Decision on whether a WHG discharge permit is required.","clause_reference":"Sec.4.1; Sec.4.2"},{"ws_code":"FLL-GAR-04","code":"REQ-04","title_de":"Nutzungsfunktion festgelegt","condition":"All four fields populated","description":"Water-body function is defined to drive subsequent design choices.","clause_reference":"Sec.4.1"},{"ws_code":"FLL-GAR-04","code":"REQ-05","title_de":"Einwirkungsklassen klassifiziert","condition":"if abdichtungs_art in {bahn_bitumen, bahn_kunststoff_elastomer, fluessigkunststoff, bahn_pe}: classes populated","description":"Wassereinwirkungsklasse, Rissklasse and Standortklasse assigned per Tab.18 for sheet-membrane sealings.","clause_reference":"Sec.6 intro; Tab.18"},{"ws_code":"FLL-GAR-04","code":"REQ-06","title_de":"Eisdruck-Schutz adressiert","condition":"if eisbildung_moeglich == true: documented ice-pressure protection","description":"If ice formation cannot be excluded, edge / connection regions are protected from ice pressure.","clause_reference":"Sec.4.4"},{"ws_code":"FLL-GAR-04","code":"REQ-07","title_de":"Baugrunduntersuchung erfolgt","condition":"All three fields populated","description":"Subsoil type identified, bearing capacity assessed, settlements addressed.","clause_reference":"Sec.4.6; Sec.8.1; Sec.9.1"},{"ws_code":"FLL-GAR-07","code":"REQ-08","title_de":"Boeschungsneigung material-konform (Tab.1)","condition":"Slope per Tab.1 row for chosen abdichtungs_art","description":"Slope ratio complies with material-specific limit per Tab.1.","clause_reference":"Sec.4.5; Tab.1"},{"ws_code":"FLL-GAR-07","code":"REQ-09","title_de":"Abdichtungssystem ausgewaehlt und nutzungsadequat","condition":"Engineer-judged selection traceable to Sec.4.7 criteria","description":"Sealing system matches usage, loads, root/rhizome regime, geometry.","clause_reference":"Sec.4.7"},{"ws_code":"FLL-GAR-07","code":"REQ-10","title_de":"CE-Kennzeichnung / EU-BauPVO / MVV-TB Konformitaet","condition":"ce_kennzeichnung_geprueft == true","description":"Product compliance verified for the chosen sealing.","clause_reference":"Sec.4.7"},{"ws_code":"FLL-GAR-22","code":"REQ-11","title_de":"Wurzel-/Rhizomfestigkeit adressiert","condition":"If required and abdichtung not inherently resistant: separate Wurzelschutzbahn","description":"If aggressive plants are present, root-/rhizome-resistant sealing or Wurzelschutzbahn is provided.","clause_reference":"Sec.4.7; Sec.10.3-10.4"},{"ws_code":"FLL-GAR-10","code":"REQ-12","title_de":"Mineral (ohne Zusatzstoffe) - Tab.3-Anforderungen","condition":"if abdichtungs_art == mineralisch_ohne_zusatzstoffe: all values within Tab.3 limits","description":"kf <= 1e-9 m/s, Kornanteil <2um >= 15%, organische Substanz <= 5%, Kalk <= 15%, Verdichtungsgrad >= 97% per Tab.3.","clause_reference":"Sec.5.1.1; Tab.3"},{"ws_code":"FLL-GAR-10","code":"REQ-13","title_de":"Mineral mit Zusatzstoffen - Tab.5-Anforderungen","condition":"if abdichtungs_art == mineralisch_mit_zusatzstoffen: Tab.5 layered dicke + Eignung","description":"Schichtdicken per Tab.5 and Eignungspruefung per Sec.5.2.3.1.","clause_reference":"Sec.5.2; Tab.5"},{"ws_code":"FLL-GAR-10","code":"REQ-14","title_de":"Beton-Anforderungen (WU) - Tab.6/8","condition":"if abdichtungs_art == mineralisch_hydraulisch: per Tab.6 row depending on d","description":"w/z, Zementgehalt, fck, Mindestdicke per Tab.6 and Tab.8 met (depending on Bauteildicke).","clause_reference":"Sec.5.3.1; Tab.6; Tab.8"},{"ws_code":"FLL-GAR-10","code":"REQ-15","title_de":"Asphalt-Anforderungen - Tab.12","condition":"if abdichtungs_art == mineralisch_bitumen: Tab.12 compliant","description":"Nenndicken for Asphaltmastix/Gussasphalt/wasserdichter Asphaltbeton per Tab.12.","clause_reference":"Sec.5.4; Tab.12"},{"ws_code":"FLL-GAR-10","code":"REQ-16","title_de":"GTD/Verbundwerkstoff - Tab.13/14/15-Anforderungen","condition":"if abdichtungs_art == verbundwerkstoff_gtd: Tab.13-15 thresholds met","description":"Bentonit, Geotextil and complete GTD product per Tab.13, Tab.14, Tab.15.","clause_reference":"Sec.5.5; Tab.13; Tab.14; Tab.15"},{"ws_code":"FLL-GAR-10","code":"REQ-17","title_de":"Bitumenbahnen - Stoffliste und Mehrlagigkeit","condition":"if abdichtungs_art == bahn_bitumen: at least 2 layers and Tab.19 type","description":"Bahnenart per Tab.19, mehrlagig per Sec.6.1.1.2, root-/rhizome-test per Sec.6.1.1.","clause_reference":"Sec.6.1; Tab.19"},{"ws_code":"FLL-GAR-10","code":"REQ-18","title_de":"Kunststoff-/Elastomerbahnen - Mindestdicke & Naht","condition":"if abdichtungs_art == bahn_kunststoff_elastomer: 1.2/1.0 + Tab.22","description":"Bahnendicke >= 1.2 mm (>= 1.0 mm prefab Gartenteich); Mindestfuegebreite per Tab.22.","clause_reference":"Sec.6.2.1.2; Sec.6.2.2.1; Tab.22"},{"ws_code":"FLL-GAR-10","code":"REQ-19","title_de":"Fluessigkunststoff - Klassifikation per Anhang 3","condition":"if abdichtungs_art == fluessigkunststoff: classes documented","description":"Klassen-Kurzzeichen-System (M/S, W1-W3, P1-P4, S1-S4, TL1-TL4, TH1-TH4) angegeben.","clause_reference":"Sec.6.3; Anhang 3"},{"ws_code":"FLL-GAR-10","code":"REQ-20","title_de":"PE-Bahnen - PEHD per Tab.24/25, PELD mit FLL-Wurzeltest","condition":"if abdichtungs_art == bahn_pe: Tab.24 thresholds and (PELD) FLL test","description":"PEHD per Tab.24 (Dichte, MFR, Russ, OIT, NCTL); PELD requires FLL root-test.","clause_reference":"Sec.6.4.1; Tab.24; Tab.25"},{"ws_code":"FLL-GAR-10","code":"REQ-21","title_de":"Stahl - Werkstoffwahl V2A/V4A/V5A/CorTen","condition":"if abdichtungs_art == stahl: Materialnachweis dokumentiert","description":"Edelstahl-Auswahl je nach Korrosionsbelastung; Verzinkungsdicke >= 100 um falls unlegiert.","clause_reference":"Sec.7.1"},{"ws_code":"FLL-GAR-10","code":"REQ-22","title_de":"Alkalisilikate - Mindestschichtdicke 25 cm + Feinkornanteil >= 20%","condition":"if abdichtungs_art == alkalisilikat: dicke >= 25 cm","description":"Schichtdicke >= 25 cm; Feinkornanteil < 0,063 mm >= 20%; Pflanzenkompatibilitaet beachten.","clause_reference":"Sec.7.2.1; Sec.7.2.1.2"},{"ws_code":"FLL-GAR-22","code":"REQ-23","title_de":"Randausbildung - Mindestueberhoehung gegen Hoechstwasserstand","condition":"freibord_zu_gelaende_cm >= 5 AND freibord_zu_bauwerk_cm >= 30 (or >= 15 if adapted)","description":"Free terrain: >= 5 cm; Building/Bauteil: >= 30 cm (or >= 15 cm with adapted fastening).","clause_reference":"Sec.4.8; Sec.9"},{"ws_code":"FLL-GAR-22","code":"REQ-24","title_de":"Schutzlagen / -schichten dimensioniert","condition":"Engineer-judged adequacy of protective layers","description":"Above and below protection per Sec.8 and Tab.26-27 based on Baugrund und Belastung.","clause_reference":"Sec.8; Tab.26; Tab.27"},{"ws_code":"FLL-GAR-22","code":"REQ-25","title_de":"Bepflanzung und Rhizom-/Wurzelschutz","condition":"Plant species reviewed and certified","description":"Plants screened against Tab.29 list; Wurzel-/Rhizompruefung as required.","clause_reference":"Sec.10; Tab.29"},{"ws_code":"FLL-GAR-25","code":"REQ-26","title_de":"Pruefkaskade vollstaendig","condition":"All test types documented as applicable","description":"Voruntersuchung, Eignungs-, Eigen-/Fremdueberwachung und Kontrollpruefungen je Werkstoff durchgefuehrt.","clause_reference":"Sec.3 (Begriffe); Sec.5.x.3; Sec.6.x.3; Sec.7.x.3"},{"ws_code":"FLL-GAR-25","code":"REQ-27","title_de":"Abnahme dokumentiert","condition":"abnahme_datum set AND maengelfrist_5_jahre == true","description":"Formal acceptance with date and signed parties.","clause_reference":"Sec.11"},{"ws_code":"FLL-GAR-25","code":"REQ-28","title_de":"Inbetriebnahme: Fuellwasser-Eignung und Faltenglaettung","condition":"Inbetriebnahme protocol prepared","description":"First-fill plan addresses Fuellwasser pH/Haerte/Inhaltsstoffe and mechanical protection during filling.","clause_reference":"Sec.12"},{"ws_code":"FLL-GAR-25","code":"REQ-29","title_de":"Inspektions-, Wartungs- und Instandsetzungskonzept","condition":"inspektion_intervall_jahr <= 1","description":"Yearly inspection plan; maintenance concept (intervals, scope); repair triggers.","clause_reference":"Sec.13"},{"ws_code":"FLL-GAR-25","code":"REQ-30","title_de":"Konformitaetszusammenfassung","condition":"compliance_verdict_final in {compliant, compliant_with_conditions}","description":"All requirements aggregated; verdict assigned; engineer + customer sign-off.","clause_reference":"All"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
